(()=>{
 const service='http://127.0.0.1:3100',launches=new Map();let activeFrame=null;
 function closeModule(){activeFrame=null;document.getElementById('ootrip-module')?.remove()}
 function note(title,text){closeModule();const pane=document.createElement('section');pane.id='ootrip-module';pane.className='ootrip-module';pane.innerHTML='<header class="ootrip-module-header"><button type="button">‹ 返回</button><h2></h2></header><div class="ootrip-module-note"></div>';pane.querySelector('h2').textContent=title;pane.querySelector('button').onclick=closeModule;pane.querySelector('.ootrip-module-note').textContent=text;document.querySelector('.phone-frame').append(pane);return pane}
 window.closeOotripModule=closeModule;
 window.openOotripModule=kind=>{if(!['fitting','journal'].includes(kind))return;const title=kind==='fitting'?'实时试衣':'穿搭手账';if(location.origin!==service){const transfer=crypto.randomUUID(),url=service+'/app/index.html?module='+kind+'&transfer='+transfer;const popup=window.open(url,'ootrip-local-app');if(popup)launches.set(popup,transfer);const pane=note(title,'试衣与手账通过本地服务运行，已在新标签页打开。若未打开，请先双击项目目录中的“启动OOTRIP.cmd”，然后点击下面的按钮。');const button=document.createElement('button');button.textContent='打开'+title;button.onclick=()=>{const win=window.open(url,'ootrip-local-app');if(win)launches.set(win,transfer)};pane.lastChild.append(button);return}const pane=note(title,'');pane.lastChild.remove();const frame=document.createElement('iframe');frame.title=title;frame.allow='camera';frame.src=(kind==='fitting'?'/fitting-screen':'/journal-screen')+'?integrated=1';activeFrame=frame;pane.append(frame)};
 window.addEventListener('message',async event=>{const d=event.data;if(event.source===document.getElementById('personal-frame')?.contentWindow&&d?.type==='ootrip:open-module')return openOotripModule(d.module);
 if(event.origin===service&&event.source===activeFrame?.contentWindow&&d?.type==='ootrip:wardrobe-rpc'){try{let result;if(d.method==='read')result=await OotripWardrobe.read();else if(d.method==='save'&&Array.isArray(d.items)&&d.items.length<=100){await OotripWardrobe.save(d.items,d.remove===true);result=true}else throw Error('不支持的衣橱操作');event.source.postMessage({type:'ootrip:wardrobe-result',id:d.id,result},service)}catch(error){event.source.postMessage({type:'ootrip:wardrobe-result',id:d.id,error:error.message},service)}return}
 if(event.origin===service&&launches.has(event.source)){if(d?.type==='ootrip:import-request'&&d.transfer===launches.get(event.source)){try{const preferences={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key&&/^ootrip(?:-|$)/.test(key)&&key!=='ootrip-wardrobe-initialized')preferences[key]=localStorage.getItem(key)}event.source.postMessage({type:'ootrip:import-data',transfer:d.transfer,preferences,items:await OotripWardrobe.read()},service)}catch{event.source.postMessage({type:'ootrip:import-data',transfer:d.transfer,error:'原网页数据暂时无法迁移，原数据仍保留'},service)}}else if(d?.type==='ootrip:wardrobe-mirror'&&Array.isArray(d.items)){await OotripWardrobe.replace(d.items).catch(()=>{})}}
 });
 const hydrate=()=>{if(typeof closetItems==='undefined')return;const custom=OotripWardrobe.cache.filter(x=>!x.id.startsWith('library-')&&!x.id.startsWith('outfit-example-')).map(x=>({...x,url:x.image}));closetItems.splice(0,closetItems.length,...custom);if(document.getElementById('closet-items')){updateClosetResults();setupClosetSides()}};
 window.addEventListener('ootrip:wardrobe-changed',hydrate);const params=new URLSearchParams(location.search),transfer=params.get('transfer');
 async function bootstrap(){await OotripWardrobe.ready;if(location.origin===service&&transfer&&window.opener){await new Promise(resolve=>{const timer=setTimeout(()=>{window.removeEventListener('message',receive);resolve()},6000);async function receive(event){if(event.source!==window.opener||!['null',service].includes(event.origin)||event.data?.type!=='ootrip:import-data'||event.data.transfer!==transfer)return;clearTimeout(timer);window.removeEventListener('message',receive);try{const payload=event.data;if(payload.error)throw Error(payload.error);for(const [key,value]of Object.entries(payload.preferences||{}))if(/^ootrip(?:-|$)/.test(key)&&!localStorage.getItem(key)&&typeof value==='string')localStorage.setItem(key,value);const existing=await OotripWardrobe.read(),ids=new Set(existing.map(x=>x.id));await OotripWardrobe.save((payload.items||[]).filter(x=>!ids.has(x.id)))}catch(error){note('数据迁移',error.message)}resolve()}window.addEventListener('message',receive);window.opener.postMessage({type:'ootrip:import-request',transfer},'*')})}hydrate();if(location.origin===service&&['fitting','journal'].includes(params.get('module'))){document.body.classList.remove('age-mode');document.getElementById('age-page')?.classList.add('hide');showWardrobe(params.get('module')==='fitting'?'closet':'me');openOotripModule(params.get('module'));history.replaceState(null,'',location.pathname)}}
 bootstrap().catch(error=>note('衣橱存储',error.message));
})();
